    private final ActivityResultLauncher<String[]> picker=registerForActivityResult(new ActivityResultContracts.OpenMultipleDocuments(), uris->{
        if(uris==null||uris.isEmpty())return; files.clear(); files.addAll(uris); mode=SEND; showSend(); startScanLoop();
    });
    private final ActivityResultLauncher<ScanOptions> scanner=registerForActivityResult(new ScanContract(), r->{if(r!=null&&r.getContents()!=null)handleQr(r.getContents());});

    private final BroadcastReceiver receiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){String a=i.getAction();
        if(WifiP2pManager.WIFI_P2P_THIS_DEVICE_CHANGED_ACTION.equals(a)){me=i.getParcelableExtra(WifiP2pManager.EXTRA_WIFI_P2P_DEVICE);if(mode==RECEIVE)updateQr();}
        else if(WifiP2pManager.WIFI_P2P_PEERS_CHANGED_ACTION.equals(a)){if(hasPerm())try{mgr.requestPeers(ch,ShareActivity.this);}catch(SecurityException e){blocked(e);}}
        else if(WifiP2pManager.WIFI_P2P_CONNECTION_CHANGED_ACTION.equals(a)){NetworkInfo n=i.getParcelableExtra(WifiP2pManager.EXTRA_NETWORK_INFO);if(n!=null&&n.isConnected()){status("Connected","Opening private transfer channel…",2);try{mgr.requestConnectionInfo(ch,ShareActivity.this);}catch(SecurityException e){blocked(e);}}else if(mode==SEND)status("Searching","Looking for a receiver",1);else if(mode==RECEIVE)status("Ready to receive","Waiting for a sender",1);}
        else if(WifiP2pManager.WIFI_P2P_STATE_CHANGED_ACTION.equals(a)&&i.getIntExtra(WifiP2pManager.EXTRA_WIFI_STATE,-1)!=WifiP2pManager.WIFI_P2P_STATE_ENABLED)status("Wi‑Fi is off","Turn on Wi‑Fi to continue",3);
    }};

    @Override protected void onCreate(Bundle b){super.onCreate(b);mgr=(WifiP2pManager)getSystemService(WIFI_P2P_SERVICE);if(mgr!=null)ch=mgr.initialize(this,getMainLooper(),()->status("Connection service restarted","Reopen OptiShare if needed",3));build();askPerm();home();}

