        LinearLayout sc=card(0xFF0F2237);LinearLayout sr=new LinearLayout(this);sr.setGravity(Gravity.CENTER_VERTICAL);dot=new View(this);LinearLayout.LayoutParams dl=new LinearLayout.LayoutParams(dp(11),dp(11));dl.setMargins(0,0,dp(10),0);sr.addView(dot,dl);LinearLayout texts=new LinearLayout(this);texts.setOrientation(LinearLayout.VERTICAL);stateTitle=t("Ready",16,Color.WHITE,true);stateSub=t("Choose Send or Receive",12,0xFF96B0C7,false);texts.addView(stateTitle);texts.addView(stateSub);sr.addView(texts,new LinearLayout.LayoutParams(0,-2,1));sc.addView(sr);LinearLayout.LayoutParams scl=new LinearLayout.LayoutParams(-1,-2);scl.setMargins(0,dp(18),0,0);root.addView(sc,scl);
