    private String deviceName(WifiP2pDevice d){return d==null||d.deviceName==null||d.deviceName.trim().isEmpty()?"Android device":d.deviceName.trim();}private String deviceStatus(int s){switch(s){case WifiP2pDevice.CONNECTED:return"Connected";case WifiP2pDevice.INVITED:return"Connecting…";case WifiP2pDevice.AVAILABLE:return"Ready to receive";case WifiP2pDevice.UNAVAILABLE:return"Busy";default:return"Nearby";}}private String name(Uri u){Cursor c=null;try{c=getContentResolver().query(u,null,null,null,null);if(c!=null&&c.moveToFirst()){int i=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(i>=0){String n=c.getString(i);if(n!=null&&!n.isEmpty())return sanitize(n);}}}finally{if(c!=null)c.close();}return"file.bin";}private long size(Uri u){Cursor c=null;try{c=getContentResolver().query(u,null,null,null,null);if(c!=null&&c.moveToFirst()){int i=c.getColumnIndex(OpenableColumns.SIZE);if(i>=0&&!c.isNull(i))return c.getLong(i);}}finally{if(c!=null)c.close();}return-1;}private long measure(Uri u)throws Exception{long total=0;byte[] b=new byte[262144];try(InputStream x=getContentResolver().openInputStream(u)){int n;while((n=x.read(b))!=-1)total+=n;}return total;}private String sanitize(String s){return s.replace("/","_").replace("\\","_").replace("\u0000","_");}private String bytes(long b){if(b<1024)return b+" B";if(b<1048576)return String.format(Locale.US,"%.1f KB",b/1024.0);if(b<1073741824L)return String.format(Locale.US,"%.2f MB",b/1048576.0);return String.format(Locale.US,"%.2f GB",b/1073741824.0);}private String safe(Throwable e){String m=e==null?null:e.getMessage();return m==null||m.trim().isEmpty()?(e==null?"Unknown error":e.getClass().getSimpleName()):m;}

    private Save openSave(String name)throws Exception{if(Build.VERSION.SDK_INT>=29){ContentValues v=new ContentValues();v.put(MediaStore.Downloads.DISPLAY_NAME,name);v.put(MediaStore.Downloads.MIME_TYPE,"application/octet-stream");v.put(MediaStore.Downloads.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS+"/OptiShare");v.put(MediaStore.Downloads.IS_PENDING,1);Uri u=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);if(u==null)throw new IOException("Could not create Downloads entry");OutputStream o=getContentResolver().openOutputStream(u);if(o==null)throw new IOException("Could not open Downloads file");return new Save(u,null,o);}File dir=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),"OptiShare");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Could not create Download/OptiShare");File f=new File(dir,name);if(f.exists())f=new File(dir,System.currentTimeMillis()+"-"+name);return new Save(null,f,new FileOutputStream(f));}private void finish(Save s){if(Build.VERSION.SDK_INT>=29&&s.uri!=null){ContentValues v=new ContentValues();v.put(MediaStore.Downloads.IS_PENDING,0);getContentResolver().update(s.uri,v,null,null);}}private void delete(Save s){try{if(s.uri!=null)getContentResolver().delete(s.uri,null,null);else if(s.file!=null)s.file.delete();}catch(Exception ignored){}}
    private void openDownloads(){try{Intent i=new Intent(Intent.ACTION_VIEW);i.setData(Uri.parse("content://com.android.providers.downloads.documents/root/downloads"));startActivity(i);}catch(Exception e){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivity(i);}}private void message(String t,String m){runOnUiThread(()->new AlertDialog.Builder(this).setTitle(t).setMessage(m).setPositiveButton("OK",null).show());}private Bitmap makeQr(String v,int s)throws Exception{BitMatrix m=new MultiFormatWriter().encode(v,BarcodeFormat.QR_CODE,s,s);Bitmap b=Bitmap.createBitmap(s,s,Bitmap.Config.RGB_565);for(int y=0;y<s;y++)for(int x=0;x<s;x++)b.setPixel(x,y,m.get(x,y)?Color.BLACK:Color.WHITE);return b;}
    private boolean ready(){return sock!=null&&sock.isConnected()&&!sock.isClosed()&&in!=null&&out!=null;}private synchronized void closeSock(){try{if(in!=null)in.close();}catch(Exception ignored){}try{if(out!=null)out.close();}catch(Exception ignored){}try{if(sock!=null)sock.close();}catch(Exception ignored){}in=null;out=null;sock=null;socketStarting=false;receiverLoop=false;}private void removeGroup(){if(mgr==null||ch==null||!hasPerm())return;try{mgr.removeGroup(ch,new WifiP2pManager.ActionListener(){public void onSuccess(){}public void onFailure(int r){}});}catch(Exception ignored){}}private void resetTransfer(){transferTitle.setText("No active transfer");transferSub.setText("Speed and progress will appear here.");bar.setProgress(0);}

    @Override protected void onResume(){super.onResume();IntentFilter f=new IntentFilter();f.addAction(WifiP2pManager.WIFI_P2P_STATE_CHANGED_ACTION);f.addAction(WifiP2pManager.WIFI_P2P_PEERS_CHANGED_ACTION);f.addAction(WifiP2pManager.WIFI_P2P_CONNECTION_CHANGED_ACTION);f.addAction(WifiP2pManager.WIFI_P2P_THIS_DEVICE_CHANGED_ACTION);ContextCompat.registerReceiver(this,receiver,f,ContextCompat.RECEIVER_NOT_EXPORTED);}@Override protected void onPause(){super.onPause();try{unregisterReceiver(receiver);}catch(Exception ignored){}}@Override protected void onDestroy(){stopScan();closeSock();io.shutdownNow();super.onDestroy();}@Override public void onBackPressed(){if(mode==HOME)super.onBackPressed();else home();}
    private static final class Meta{final String name;final long size;final byte[] hash;Meta(String n,long s,byte[] h){name=n;size=s;hash=h;}}private static final class Save{final Uri uri;final File file;final OutputStream out;Save(Uri u,File f,OutputStream o){uri=u;file=f;out=o;}}
